    measured: 'WATRDrip 64 个事件（chirp_fit.py）：起始 1.5kHz（四分位 0.87–2.25k）、斜率中位 0（−3…+7.7 倍频程/秒）、持续 0.06s、衰减 63/s（37–122）。',
    params: [{ k: 'size', label: '大小', min: 0, max: 1, step: 0.05, def: 0.5 }, { k: 'force', label: '力度', min: 0, max: 1, step: 0.05, def: 0.5 }],
    presets: [{ name: '小水滴', opts: { size: 0.2, force: 0.4 } }, { name: '普通水滴', opts: { size: 0.5, force: 0.5 } }, { name: '大水滴', opts: { size: 0.85, force: 0.8 } }],
    refs: [{ name: 'WATRDrip Drop Tonal', path: 'casual UI/WATRDrip_MATERIAL LIQUID-Drop Tonal_B00M_CUCK.wav', offset: 0.1116, dur: 0.37 }],
    loud: o => 0.45 + 0.55 * o.force,
