  // ---------- 闪光 sparkle ----------
  // v2（tool/C/tonal_fit.py 在 MAGShim/MUSCChim 319 段上逐帧跟踪）：闪光声 89% 的能量是音调成分（四分位 68–97%），
  // 同时约 52 条高频正弦（四分位 32–67），频率中位 10kHz（四分位 6.3–13.4k），单条片段 0.12s（90% 分位 0.57s），非谐和（谐和比例 0.20 ≈ 随机 0.18），
  // 颤动约 4 音分、漂移 ±0.2 倍频程/秒。v1 用"每秒 76 颗 25ms 短音"，同时只有约 2 条，远比真录音稀疏。
  function partialCloud(L, R, o) {   // o: rate(t) 每秒新生条数, f 中位, s ln标准差, life 中位秒, drift 倍频程/秒均值, amp(t)；返回 RMS=1
    const out = new Float64Array(L), T = L / SR; let t = -o.life;
    const rmax = o.rmax;
    while (true) {
      t += -Math.log(1 - R() * 0.999) / rmax; if (t >= T) break;
      if (R() > o.rate(Math.max(0, t)) / rmax) continue;
      const lf = o.life * Math.exp(R.g() * 0.6), f0 = clamp((o.fc ? o.fc(Math.max(0, t)) : o.f) * Math.exp(R.g() * o.s), 2000, 17500), dr = o.drift + R.g() * 0.2, a = Math.exp(R.g() * 0.6);
      const ns = Math.round(t * SR), N = Math.max(64, Math.round(lf * SR)), n0 = Math.max(0, ns), n1 = Math.min(L, ns + N);
      const ph0 = R() * 6.283; let zr = Math.cos(ph0), zi = Math.sin(ph0), wr = 1, wi = 0;
      const ew = Math.PI / N; let er = Math.cos(ew * (n0 - ns)), ei = Math.sin(ew * (n0 - ns)); const cr = Math.cos(ew), ci = Math.sin(ew);
      const vr = 3 + R() * 4, vd = 0.0023 * (0.5 + R());
      for (let n = n0; n < n1; n++) {
        if (((n - n0) & 31) === 0) { const tt = (n - ns) / SR, f = clamp(f0 * Math.pow(2, dr * tt + vd * Math.sin(6.2832 * vr * tt)), 1000, 19000), w = 6.2832 * f / SR; wr = Math.cos(w); wi = Math.sin(w); const m = 1 / Math.sqrt(zr * zr + zi * zi); zr *= m; zi *= m; }
        out[n] += zi * a * ei * ei;
        const nr = zr * wr - zi * wi; zi = zr * wi + zi * wr; zr = nr; const e2 = er * cr - ei * ci; ei = er * ci + ei * cr; er = e2;
      }
    }
    return air().normRms(out);
  }
  S.def('sparkle', {
    group: '魔法', name: '闪光',
    desc: '几十条高频、频率互不成整数倍（非谐和）的细小正弦同时闪烁（各自短暂出现又消失，略有颤动），再加一层很淡的高频"沙沙"；方向参数让新出现的正弦频率中心随时间整体上扬或下行（±1 时全程 1.5 倍频程）。',
    measured: 'MAGShim/MUSCChim 319 段逐帧音调轨迹：音调能量占比 89%、同时约 52 条、频率中位 10kHz（6.3–13.4k）、片段 0.12s（长的 0.57s）、非谐和、颤动 4 音分；起音中位 0.43s、峰后掉 20dB 0.71s。上扬/下行的扫频幅度是设计值。',
    params: [{ k: 'density', label: '密度', min: 0, max: 1, step: 0.05, def: 0.5 }, { k: 'bright', label: '亮度', min: 0, max: 1, step: 0.05, def: 0.5 }, { k: 'dur', label: '时长(秒)', min: 0.15, max: 2, step: 0.05, def: 0.6 },
      { k: 'dir', label: '方向(下行↔上扬)', min: -1, max: 1, step: 0.1, def: 0 }],
    presets: [{ name: '短闪（拾取）', opts: { density: 0.4, bright: 0.6, dur: 0.3 } }, { name: '仙尘', opts: { density: 0.6, bright: 0.5, dur: 1.0 } }, { name: '上扬闪光（升级）', opts: { density: 0.7, bright: 0.6, dur: 1.0, dir: 1 } }, { name: '下落光尘', opts: { density: 0.5, bright: 0.4, dur: 1.2, dir: -1 } }],
    refs: [{ name: 'MAGShim Fairy Dust', path: 'casual UI/MAGShim_SHIMMER-Fairy Dust_B00M_CUCK.wav', offset: 8.6978, dur: 1.5 }, { name: 'MAGShim Short Highlight', path: 'casual UI/MAGShim_SHIMMER-Short Highlight_B00M_CUCK.wav', offset: 2.6893, dur: 1.07 }],
    loud: o => 0.5 + 0.3 * o.density,
    gen: o => {
      const R = S.rng(o.seed), T = clamp(o.dur, 0.1, 4), L = Math.round(T * SR);
      const att = Math.min(0.43, T * 0.3) * (o.dir > 0 ? 1.6 : 0.6), dec = T - att;
      const amp = t => t < att ? Math.pow(t / att, 1.5) : Math.pow(10, -90 * (t - att) / Math.max(0.05, dec) / 20);   // 输出乘 √amp：峰后 dB 线性衰减，结尾到 −45dB（第一轮结尾还在 −13dB 就被淡出硬切）
      const life = 0.18, poly = 20 + 64 * o.density;          // density 0.5 → 同时约 52 条（实测中位）
      const rate = t => poly / life * (0.15 + 0.85 * amp(t));
      // 方向：新生正弦的频率中心随时间扫（dir=±1 时全程 ±1.5 倍频程，中点在亮度决定的频率上）；每条正弦自身再略漂移
      const dir = clamp(o.dir || 0, -1, 1), fm = 10000 * Math.pow(2, (o.bright - 0.5) * 1.2);
      const y = partialCloud(L, R, { rate, rmax: poly / life, fc: t => fm * Math.pow(2, dir * 1.5 * (t / T - 0.5)), s: 0.45, life, drift: dir * 1.0 });
      // 整体包络（新生条数已随 amp 变；再乘一次让起止更干净）+ 高频沙沙（能量约 11%，实测音调占比 89%）
      const hiss = air().normRms(S.biquad(S.biquad(S.pink(T, R), 'hp', 2500, 0.7), 'highshelf', 6000, 0.7, 9));
      for (let n = 0; n < L; n++) { const a = amp(n / SR); y[n] = (y[n] + hiss[n] * 0.35) * Math.sqrt(a); }
      return fadeEdges(y, 0.003, 0.04);
    }
  });

